import { sql } from 'drizzle-orm';
import { MAX_STOCK_QUANTITY } from '@solmira/contracts';
import {
  bigint,
  check,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

// Conventions (as in identity): UUIDv7 ids generated by the application, timestamptz, money as
// bigint minor units, statuses as text + CHECK. Every tenant-owned table has organization_id and a
// unique (organization_id, id) key so other tables can reference it with a composite foreign key:
// a reference into another tenant is then not just filtered out, it cannot be written at all.

const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const createdAt = () => timestamptz('created_at').notNull().defaultNow();
const updatedAt = () => timestamptz('updated_at').notNull().defaultNow();
const money = (name: string) => bigint(name, { mode: 'number' });
const inList = (values: readonly string[]) =>
  sql.raw(values.map((value) => `'${value}'`).join(', '));

// ---- member directory ---------------------------------------------------------------------------

/**
 * A local copy of the organization members this service references (warehouse managers). Identity
 * owns members; this table exists so that (1) a manager can be enforced by a composite foreign key
 * inside this database and (2) lists can show manager names without a call per row.
 */
export const memberDirectory = pgTable(
  'member_directory',
  {
    organizationId: uuid('organization_id').notNull(),
    memberId: uuid('member_id').notNull(),
    userId: uuid('user_id').notNull(),
    fullName: text('full_name').notNull(),
    email: text('email').notNull(),
    status: text('status', { enum: ['active', 'suspended'] }).notNull(),
    syncedAt: timestamptz('synced_at').notNull().defaultNow(),
  },
  (table) => [primaryKey({ columns: [table.organizationId, table.memberId] })],
);

// ---- categories ---------------------------------------------------------------------------------

export const categories = pgTable(
  'categories',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    parentId: uuid('parent_id'),
    name: text('name').notNull(),
    slug: text('slug').notNull(),
    description: text('description'),
    sortOrder: integer('sort_order').notNull().default(0),
    status: text('status', { enum: ['ACTIVE', 'ARCHIVED'] })
      .notNull()
      .default('ACTIVE'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('categories_org_id_key').on(table.organizationId, table.id),
    unique('categories_org_slug_key').on(table.organizationId, table.slug),
    // A child must live in the same organization as its parent.
    foreignKey({
      name: 'categories_parent_fk',
      columns: [table.organizationId, table.parentId],
      foreignColumns: [table.organizationId, table.id],
    }).onDelete('restrict'),
    index('categories_org_parent_idx').on(table.organizationId, table.parentId),
    check('categories_status_check', sql`${table.status} in ('ACTIVE', 'ARCHIVED')`),
    check('categories_not_own_parent_check', sql`${table.parentId} is distinct from ${table.id}`),
  ],
);

// ---- suppliers ----------------------------------------------------------------------------------

export const PAYMENT_TERMS_VALUES = [
  'PREPAID',
  'COD',
  'NET_15',
  'NET_30',
  'NET_45',
  'NET_60',
  'NET_90',
] as const;

export const suppliers = pgTable(
  'suppliers',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    companyName: text('company_name').notNull(),
    contactName: text('contact_name'),
    email: text('email'),
    phone: text('phone'),
    addressLine: text('address_line'),
    city: text('city'),
    country: text('country'),
    paymentTerms: text('payment_terms', { enum: PAYMENT_TERMS_VALUES }).notNull().default('NET_30'),
    leadTimeDays: integer('lead_time_days').notNull().default(14),
    status: text('status', { enum: ['ACTIVE', 'INACTIVE'] })
      .notNull()
      .default('ACTIVE'),
    notes: text('notes'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('suppliers_org_id_key').on(table.organizationId, table.id),
    // Guards against accidental duplicates of the same company within one organization.
    uniqueIndex('suppliers_org_company_name_key').on(
      table.organizationId,
      sql`lower(${table.companyName})`,
    ),
    index('suppliers_org_status_idx').on(table.organizationId, table.status),
    check('suppliers_status_check', sql`${table.status} in ('ACTIVE', 'INACTIVE')`),
    check(
      'suppliers_payment_terms_check',
      sql`${table.paymentTerms} in (${inList(PAYMENT_TERMS_VALUES)})`,
    ),
    check('suppliers_lead_time_check', sql`${table.leadTimeDays} between 0 and 365`),
    check(
      'suppliers_country_check',
      sql`${table.country} is null or ${table.country} ~ '^[A-Z]{2}$'`,
    ),
  ],
);

// ---- warehouses ---------------------------------------------------------------------------------

export const warehouses = pgTable(
  'warehouses',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    code: text('code').notNull(),
    name: text('name').notNull(),
    description: text('description'),
    addressLine: text('address_line'),
    city: text('city'),
    country: text('country'),
    // References member_directory (organization_id, member_id); FK defined in the RLS migration
    // with ON DELETE SET NULL (manager_member_id), which drizzle cannot express.
    managerMemberId: uuid('manager_member_id'),
    status: text('status', { enum: ['ACTIVE', 'INACTIVE'] })
      .notNull()
      .default('ACTIVE'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('warehouses_org_id_key').on(table.organizationId, table.id),
    // Tenant-scoped: two organizations may both have WH-DHK.
    unique('warehouses_org_code_key').on(table.organizationId, table.code),
    check('warehouses_status_check', sql`${table.status} in ('ACTIVE', 'INACTIVE')`),
    check('warehouses_code_check', sql`${table.code} ~ '^[A-Z0-9][A-Z0-9-]{1,19}$'`),
    check(
      'warehouses_country_check',
      sql`${table.country} is null or ${table.country} ~ '^[A-Z]{2}$'`,
    ),
  ],
);

// ---- products -----------------------------------------------------------------------------------

export const products = pgTable(
  'products',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    categoryId: uuid('category_id'),
    supplierId: uuid('supplier_id'),
    name: text('name').notNull(),
    slug: text('slug').notNull(),
    description: text('description'),
    brand: text('brand'),
    status: text('status', { enum: ['DRAFT', 'ACTIVE', 'INACTIVE', 'ARCHIVED'] })
      .notNull()
      .default('DRAFT'),
    baseCostMinor: money('base_cost_minor'),
    basePriceMinor: money('base_price_minor').notNull(),
    currency: text('currency').notNull(),
    taxCategory: text('tax_category', { enum: ['STANDARD', 'REDUCED', 'ZERO', 'EXEMPT'] })
      .notNull()
      .default('STANDARD'),
    weightGrams: integer('weight_grams'),
    lengthMm: integer('length_mm'),
    widthMm: integer('width_mm'),
    heightMm: integer('height_mm'),
    archivedAt: timestamptz('archived_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('products_org_id_key').on(table.organizationId, table.id),
    unique('products_org_slug_key').on(table.organizationId, table.slug),
    foreignKey({
      name: 'products_category_fk',
      columns: [table.organizationId, table.categoryId],
      foreignColumns: [categories.organizationId, categories.id],
    }).onDelete('restrict'),
    foreignKey({
      name: 'products_supplier_fk',
      columns: [table.organizationId, table.supplierId],
      foreignColumns: [suppliers.organizationId, suppliers.id],
    }).onDelete('restrict'),
    // Default list: newest changes first, optionally filtered by status.
    index('products_org_status_updated_idx').on(
      table.organizationId,
      table.status,
      table.updatedAt.desc(),
    ),
    index('products_org_updated_idx').on(table.organizationId, table.updatedAt.desc()),
    index('products_org_created_idx').on(table.organizationId, table.createdAt),
    index('products_org_category_idx').on(table.organizationId, table.categoryId),
    index('products_org_supplier_idx').on(table.organizationId, table.supplierId),
    index('products_org_price_idx').on(table.organizationId, table.basePriceMinor),
    index('products_org_brand_idx').on(table.organizationId, sql`lower(${table.brand})`),
    check(
      'products_status_check',
      sql`${table.status} in ('DRAFT', 'ACTIVE', 'INACTIVE', 'ARCHIVED')`,
    ),
    check(
      'products_tax_category_check',
      sql`${table.taxCategory} in ('STANDARD', 'REDUCED', 'ZERO', 'EXEMPT')`,
    ),
    check('products_currency_check', sql`${table.currency} ~ '^[A-Z]{3}$'`),
    check(
      'products_money_check',
      sql`${table.basePriceMinor} >= 0 and (${table.baseCostMinor} is null or ${table.baseCostMinor} >= 0)`,
    ),
    check(
      'products_dimensions_check',
      sql`coalesce(${table.weightGrams}, 0) >= 0 and coalesce(${table.lengthMm}, 0) >= 0
          and coalesce(${table.widthMm}, 0) >= 0 and coalesce(${table.heightMm}, 0) >= 0`,
    ),
    check(
      'products_archived_at_check',
      sql`(${table.status} = 'ARCHIVED') = (${table.archivedAt} is not null)`,
    ),
  ],
);

// ---- product variants ---------------------------------------------------------------------------

export const productVariants = pgTable(
  'product_variants',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    productId: uuid('product_id').notNull(),
    sku: text('sku').notNull(),
    barcode: text('barcode'),
    name: text('name').notNull(),
    attributes: jsonb('attributes').$type<Record<string, string>>().notNull().default({}),
    priceMinor: money('price_minor'),
    costMinor: money('cost_minor'),
    weightGrams: integer('weight_grams'),
    status: text('status', { enum: ['ACTIVE', 'INACTIVE', 'ARCHIVED'] })
      .notNull()
      .default('ACTIVE'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('product_variants_org_id_key').on(table.organizationId, table.id),
    // Lets purchase lines prove, by foreign key, that their variant belongs to their product.
    unique('product_variants_org_product_id_key').on(
      table.organizationId,
      table.productId,
      table.id,
    ),
    // Organization A variant -> organization B product is structurally impossible.
    foreignKey({
      name: 'product_variants_product_fk',
      columns: [table.organizationId, table.productId],
      foreignColumns: [products.organizationId, products.id],
    }).onDelete('restrict'),
    // SKU: unique per organization among live variants. Archiving frees the code; order lines
    // snapshot the SKU they were sold under, so history does not depend on the variant row.
    uniqueIndex('product_variants_org_sku_live_key')
      .on(table.organizationId, table.sku)
      .where(sql`${table.status} <> 'ARCHIVED'`),
    uniqueIndex('product_variants_org_barcode_live_key')
      .on(table.organizationId, table.barcode)
      .where(sql`${table.barcode} is not null and ${table.status} <> 'ARCHIVED'`),
    index('product_variants_org_product_idx').on(table.organizationId, table.productId),
    check(
      'product_variants_status_check',
      sql`${table.status} in ('ACTIVE', 'INACTIVE', 'ARCHIVED')`,
    ),
    // Defence in depth for the normalisation the API performs.
    check(
      'product_variants_sku_normalised_check',
      sql`${table.sku} = upper(btrim(${table.sku})) and ${table.sku} <> ''`,
    ),
    check(
      'product_variants_money_check',
      sql`coalesce(${table.priceMinor}, 0) >= 0 and coalesce(${table.costMinor}, 0) >= 0`,
    ),
  ],
);

// ---- product images -----------------------------------------------------------------------------

export const productImages = pgTable(
  'product_images',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    productId: uuid('product_id').notNull(),
    objectKey: text('object_key').notNull().unique(),
    originalFilename: text('original_filename').notNull(),
    contentType: text('content_type').notNull(),
    fileSize: integer('file_size').notNull(),
    sortOrder: integer('sort_order').notNull(),
    altText: text('alt_text'),
    createdAt: createdAt(),
  },
  (table) => [
    unique('product_images_org_id_key').on(table.organizationId, table.id),
    foreignKey({
      name: 'product_images_product_fk',
      columns: [table.organizationId, table.productId],
      foreignColumns: [products.organizationId, products.id],
    }).onDelete('cascade'),
    index('product_images_org_product_idx').on(
      table.organizationId,
      table.productId,
      table.sortOrder,
    ),
    check(
      'product_images_content_type_check',
      sql`${table.contentType} in ('image/jpeg', 'image/png', 'image/webp')`,
    ),
    check('product_images_size_check', sql`${table.fileSize} between 1 and 5242880`),
    // The storage key must live under the row's own organization prefix.
    check(
      'product_images_key_prefix_check',
      sql`${table.objectKey} like ('organizations/' || ${table.organizationId}::text || '/products/' || ${table.productId}::text || '/%')`,
    ),
  ],
);

// ---- inventory ----------------------------------------------------------------------------------

export const MOVEMENT_TYPE_VALUES = [
  'ADJUSTMENT',
  'TRANSFER_OUT',
  'TRANSFER_IN',
  'RESERVATION',
  'RELEASE',
  'PURCHASE_RECEIPT',
] as const;
export const ADJUSTMENT_REASON_VALUES = [
  'RECEIVED',
  'COUNT',
  'DAMAGED',
  'LOST',
  'FOUND',
  'RETURNED',
  'CORRECTION',
] as const;

/**
 * Current stock of one variant in one warehouse. The counters are the fast path that reservation
 * guards run against; the ledger (inventory_movements) is the history they can be rebuilt from.
 */
export const inventoryLevels = pgTable(
  'inventory_levels',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    warehouseId: uuid('warehouse_id').notNull(),
    variantId: uuid('variant_id').notNull(),
    onHand: integer('on_hand').notNull().default(0),
    reserved: integer('reserved').notNull().default(0),
    // Computed by the database, so it can never disagree with the two counters.
    available: integer('available').generatedAlwaysAs(sql`on_hand - reserved`),
    reorderPoint: integer('reorder_point'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('inventory_levels_org_id_key').on(table.organizationId, table.id),
    unique('inventory_levels_org_warehouse_variant_key').on(
      table.organizationId,
      table.warehouseId,
      table.variantId,
    ),
    foreignKey({
      name: 'inventory_levels_warehouse_fk',
      columns: [table.organizationId, table.warehouseId],
      foreignColumns: [warehouses.organizationId, warehouses.id],
    }).onDelete('restrict'),
    foreignKey({
      name: 'inventory_levels_variant_fk',
      columns: [table.organizationId, table.variantId],
      foreignColumns: [productVariants.organizationId, productVariants.id],
    }).onDelete('restrict'),
    // Stock of one variant across warehouses.
    index('inventory_levels_org_variant_idx').on(table.organizationId, table.variantId),
    index('inventory_levels_org_updated_idx').on(table.organizationId, table.updatedAt.desc()),
    // The oversell guard of last resort: whatever the code does, these cannot be violated.
    check(
      'inventory_levels_quantities_check',
      sql`${table.onHand} >= 0 and ${table.reserved} >= 0 and ${table.reserved} <= ${table.onHand}
          and ${table.onHand} <= ${sql.raw(String(MAX_STOCK_QUANTITY))}`,
    ),
    check(
      'inventory_levels_reorder_point_check',
      sql`${table.reorderPoint} is null or ${table.reorderPoint} >= 0`,
    ),
  ],
);

/**
 * Append-only stock ledger: one row per change to a level, with both deltas and the balances
 * after it. Updates and deletes are refused by the database (see migration 0003).
 */
export const inventoryMovements = pgTable(
  'inventory_movements',
  {
    id: uuid('id').primaryKey(),
    // Assigned by the database at insert time, while the level's row lock is held, so per level it
    // is exactly the order changes were applied. created_at alone cannot give that: concurrent
    // transactions start in one order and apply in lock order.
    sequence: bigint('sequence', { mode: 'number' }).generatedAlwaysAsIdentity(),
    organizationId: uuid('organization_id').notNull(),
    inventoryLevelId: uuid('inventory_level_id').notNull(),
    type: text('type', { enum: MOVEMENT_TYPE_VALUES }).notNull(),
    reason: text('reason', { enum: ADJUSTMENT_REASON_VALUES }),
    onHandChange: integer('on_hand_change').notNull(),
    reservedChange: integer('reserved_change').notNull(),
    onHandAfter: integer('on_hand_after').notNull(),
    reservedAfter: integer('reserved_after').notNull(),
    referenceType: text('reference_type', {
      enum: ['TRANSFER', 'RESERVATION', 'PURCHASE_RECEIPT'],
    }),
    referenceId: uuid('reference_id'),
    note: text('note'),
    actorId: uuid('actor_id'),
    correlationId: text('correlation_id').notNull(),
    // Wall-clock time of the insert, not the transaction start that now() would give.
    createdAt: timestamptz('created_at')
      .notNull()
      .default(sql`clock_timestamp()`),
  },
  (table) => [
    unique('inventory_movements_org_id_key').on(table.organizationId, table.id),
    unique('inventory_movements_sequence_key').on(table.sequence),
    foreignKey({
      name: 'inventory_movements_level_fk',
      columns: [table.organizationId, table.inventoryLevelId],
      foreignColumns: [inventoryLevels.organizationId, inventoryLevels.id],
    }).onDelete('restrict'),
    index('inventory_movements_org_level_sequence_idx').on(
      table.organizationId,
      table.inventoryLevelId,
      table.sequence.desc(),
    ),
    index('inventory_movements_org_sequence_idx').on(table.organizationId, table.sequence.desc()),
    index('inventory_movements_org_created_idx').on(table.organizationId, table.createdAt),
    index('inventory_movements_org_reference_idx').on(
      table.organizationId,
      table.referenceType,
      table.referenceId,
    ),
    check(
      'inventory_movements_type_check',
      sql`${table.type} in (${inList(MOVEMENT_TYPE_VALUES)})`,
    ),
    check(
      'inventory_movements_reason_check',
      sql`(${table.type} = 'ADJUSTMENT') = (${table.reason} is not null)
          and (${table.reason} is null or ${table.reason} in (${inList(ADJUSTMENT_REASON_VALUES)}))`,
    ),
    // Each type moves exactly one counter, in one direction.
    check(
      'inventory_movements_change_check',
      sql`case ${table.type}
            when 'ADJUSTMENT' then ${table.onHandChange} <> 0 and ${table.reservedChange} = 0
            when 'TRANSFER_OUT' then ${table.onHandChange} < 0 and ${table.reservedChange} = 0
            when 'TRANSFER_IN' then ${table.onHandChange} > 0 and ${table.reservedChange} = 0
            when 'RESERVATION' then ${table.onHandChange} = 0 and ${table.reservedChange} > 0
            when 'RELEASE' then ${table.onHandChange} = 0 and ${table.reservedChange} < 0
            when 'PURCHASE_RECEIPT' then ${table.onHandChange} > 0 and ${table.reservedChange} = 0
          end`,
    ),
    check(
      'inventory_movements_balance_check',
      sql`${table.onHandAfter} >= 0 and ${table.reservedAfter} >= 0 and ${table.reservedAfter} <= ${table.onHandAfter}`,
    ),
    check(
      'inventory_movements_reference_check',
      sql`(${table.referenceType} is null) = (${table.referenceId} is null)`,
    ),
  ],
);

/** A hold on stock of one variant in one warehouse. Orders reuse it in phase 6. */
export const inventoryReservations = pgTable(
  'inventory_reservations',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    inventoryLevelId: uuid('inventory_level_id').notNull(),
    quantity: integer('quantity').notNull(),
    status: text('status', { enum: ['ACTIVE', 'RELEASED'] })
      .notNull()
      .default('ACTIVE'),
    reference: text('reference').notNull(),
    note: text('note'),
    createdBy: uuid('created_by'),
    releasedBy: uuid('released_by'),
    releasedAt: timestamptz('released_at'),
    createdAt: createdAt(),
  },
  (table) => [
    unique('inventory_reservations_org_id_key').on(table.organizationId, table.id),
    foreignKey({
      name: 'inventory_reservations_level_fk',
      columns: [table.organizationId, table.inventoryLevelId],
      foreignColumns: [inventoryLevels.organizationId, inventoryLevels.id],
    }).onDelete('restrict'),
    index('inventory_reservations_org_status_created_idx').on(
      table.organizationId,
      table.status,
      table.createdAt.desc(),
    ),
    index('inventory_reservations_org_level_idx').on(table.organizationId, table.inventoryLevelId),
    check('inventory_reservations_status_check', sql`${table.status} in ('ACTIVE', 'RELEASED')`),
    check('inventory_reservations_quantity_check', sql`${table.quantity} > 0`),
    check(
      'inventory_reservations_released_check',
      sql`(${table.status} = 'RELEASED') = (${table.releasedAt} is not null)`,
    ),
  ],
);

// ---- purchasing ---------------------------------------------------------------------------------

export const PURCHASE_ORDER_STATUS_VALUES = [
  'DRAFT',
  'SUBMITTED',
  'APPROVED',
  'PARTIALLY_RECEIVED',
  'RECEIVED',
  'CANCELLED',
] as const;

/**
 * Per-organization, per-year counter behind PO-2026-000001. Incremented with an upsert inside the
 * transaction that creates the order, so numbers are never reused within a tenant, and a rolled
 * back creation gives its number back.
 */
export const purchaseOrderCounters = pgTable(
  'purchase_order_counters',
  {
    organizationId: uuid('organization_id').notNull(),
    year: integer('year').notNull(),
    lastValue: integer('last_value').notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.organizationId, table.year] }),
    check('purchase_order_counters_value_check', sql`${table.lastValue} > 0`),
  ],
);

export const purchaseOrders = pgTable(
  'purchase_orders',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    number: text('number').notNull(),
    supplierId: uuid('supplier_id').notNull(),
    warehouseId: uuid('warehouse_id').notNull(),
    status: text('status', { enum: PURCHASE_ORDER_STATUS_VALUES }).notNull().default('DRAFT'),
    currency: text('currency').notNull(),
    expectedDeliveryDate: date('expected_delivery_date', { mode: 'string' }),
    notes: text('notes'),
    subtotalMinor: money('subtotal_minor').notNull().default(0),
    taxMinor: money('tax_minor').notNull().default(0),
    shippingMinor: money('shipping_minor').notNull().default(0),
    totalMinor: money('total_minor').notNull().default(0),
    createdBy: uuid('created_by'),
    submittedBy: uuid('submitted_by'),
    submittedAt: timestamptz('submitted_at'),
    approvedBy: uuid('approved_by'),
    approvedAt: timestamptz('approved_at'),
    receivedAt: timestamptz('received_at'),
    cancelledBy: uuid('cancelled_by'),
    cancelledAt: timestamptz('cancelled_at'),
    cancellationReason: text('cancellation_reason'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('purchase_orders_org_id_key').on(table.organizationId, table.id),
    // Receipts reference (organization, order, warehouse): stock can only arrive where ordered.
    unique('purchase_orders_org_id_warehouse_key').on(
      table.organizationId,
      table.id,
      table.warehouseId,
    ),
    unique('purchase_orders_org_number_key').on(table.organizationId, table.number),
    foreignKey({
      name: 'purchase_orders_supplier_fk',
      columns: [table.organizationId, table.supplierId],
      foreignColumns: [suppliers.organizationId, suppliers.id],
    }).onDelete('restrict'),
    foreignKey({
      name: 'purchase_orders_warehouse_fk',
      columns: [table.organizationId, table.warehouseId],
      foreignColumns: [warehouses.organizationId, warehouses.id],
    }).onDelete('restrict'),
    index('purchase_orders_org_created_idx').on(table.organizationId, table.createdAt.desc()),
    index('purchase_orders_org_status_created_idx').on(
      table.organizationId,
      table.status,
      table.createdAt.desc(),
    ),
    index('purchase_orders_org_supplier_created_idx').on(
      table.organizationId,
      table.supplierId,
      table.createdAt.desc(),
    ),
    index('purchase_orders_org_warehouse_created_idx').on(
      table.organizationId,
      table.warehouseId,
      table.createdAt.desc(),
    ),
    check(
      'purchase_orders_status_check',
      sql`${table.status} in (${inList(PURCHASE_ORDER_STATUS_VALUES)})`,
    ),
    check('purchase_orders_currency_check', sql`${table.currency} ~ '^[A-Z]{3}$'`),
    check('purchase_orders_number_check', sql`${table.number} ~ '^PO-[0-9]{4}-[0-9]{6,}$'`),
    check(
      'purchase_orders_money_check',
      sql`${table.subtotalMinor} >= 0 and ${table.taxMinor} >= 0 and ${table.shippingMinor} >= 0
          and ${table.totalMinor} = ${table.subtotalMinor} + ${table.taxMinor} + ${table.shippingMinor}`,
    ),
    // Lifecycle timestamps exist exactly when the order has passed that step (a cancelled order
    // keeps whatever steps it had reached).
    check(
      'purchase_orders_submitted_check',
      sql`case ${table.status}
            when 'DRAFT' then ${table.submittedAt} is null
            when 'CANCELLED' then true
            else ${table.submittedAt} is not null and ${table.submittedBy} is not null
          end`,
    ),
    check(
      'purchase_orders_approved_check',
      sql`case
            when ${table.status} in ('DRAFT', 'SUBMITTED') then ${table.approvedAt} is null
            when ${table.status} = 'CANCELLED' then ${table.approvedAt} is null or ${table.submittedAt} is not null
            else ${table.approvedAt} is not null and ${table.approvedBy} is not null
          end`,
    ),
    check(
      'purchase_orders_received_check',
      sql`(${table.status} = 'RECEIVED') = (${table.receivedAt} is not null)`,
    ),
    check(
      'purchase_orders_cancelled_check',
      sql`(${table.status} = 'CANCELLED') = (${table.cancelledAt} is not null)
          and (${table.cancelledAt} is null or ${table.cancellationReason} is not null)`,
    ),
  ],
);

export const purchaseOrderItems = pgTable(
  'purchase_order_items',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    purchaseOrderId: uuid('purchase_order_id').notNull(),
    productId: uuid('product_id').notNull(),
    variantId: uuid('variant_id').notNull(),
    orderedQuantity: integer('ordered_quantity').notNull(),
    receivedQuantity: integer('received_quantity').notNull().default(0),
    unitCostMinor: money('unit_cost_minor').notNull(),
    taxRateBps: integer('tax_rate_bps').notNull().default(0),
    subtotalMinor: money('subtotal_minor').notNull(),
    taxMinor: money('tax_minor').notNull(),
    totalMinor: money('total_minor').notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('purchase_order_items_org_id_key').on(table.organizationId, table.id),
    // Receipt lines reference (organization, order, line): a line of another order cannot be used.
    unique('purchase_order_items_org_order_id_key').on(
      table.organizationId,
      table.purchaseOrderId,
      table.id,
    ),
    unique('purchase_order_items_org_order_variant_key').on(
      table.organizationId,
      table.purchaseOrderId,
      table.variantId,
    ),
    foreignKey({
      name: 'purchase_order_items_order_fk',
      columns: [table.organizationId, table.purchaseOrderId],
      foreignColumns: [purchaseOrders.organizationId, purchaseOrders.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'purchase_order_items_product_fk',
      columns: [table.organizationId, table.productId],
      foreignColumns: [products.organizationId, products.id],
    }).onDelete('restrict'),
    // The variant must belong to the organization and to this line's product.
    foreignKey({
      name: 'purchase_order_items_variant_fk',
      columns: [table.organizationId, table.productId, table.variantId],
      foreignColumns: [
        productVariants.organizationId,
        productVariants.productId,
        productVariants.id,
      ],
    }).onDelete('restrict'),
    index('purchase_order_items_org_variant_idx').on(table.organizationId, table.variantId),
    check(
      'purchase_order_items_quantity_check',
      sql`${table.orderedQuantity} > 0 and ${table.receivedQuantity} >= 0
          and ${table.receivedQuantity} <= ${table.orderedQuantity}`,
    ),
    check(
      'purchase_order_items_amounts_check',
      sql`${table.unitCostMinor} >= 0 and ${table.taxRateBps} between 0 and 10000
          and ${table.subtotalMinor} = ${table.orderedQuantity}::bigint * ${table.unitCostMinor}
          and ${table.taxMinor} >= 0
          and ${table.totalMinor} = ${table.subtotalMinor} + ${table.taxMinor}`,
    ),
  ],
);

/** One receiving operation: who received what, when, where, against which order. Append-only. */
export const purchaseReceipts = pgTable(
  'purchase_receipts',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    purchaseOrderId: uuid('purchase_order_id').notNull(),
    warehouseId: uuid('warehouse_id').notNull(),
    receivedBy: uuid('received_by'),
    receivedAt: timestamptz('received_at')
      .notNull()
      .default(sql`clock_timestamp()`),
    note: text('note'),
    idempotencyKey: text('idempotency_key').notNull(),
    /** SHA-256 of the normalised request, to tell a retry from a different request reusing a key. */
    requestHash: text('request_hash').notNull(),
    correlationId: text('correlation_id').notNull(),
  },
  (table) => [
    unique('purchase_receipts_org_id_key').on(table.organizationId, table.id),
    unique('purchase_receipts_org_id_order_key').on(
      table.organizationId,
      table.id,
      table.purchaseOrderId,
    ),
    unique('purchase_receipts_org_idempotency_key').on(table.organizationId, table.idempotencyKey),
    foreignKey({
      name: 'purchase_receipts_order_fk',
      columns: [table.organizationId, table.purchaseOrderId, table.warehouseId],
      foreignColumns: [
        purchaseOrders.organizationId,
        purchaseOrders.id,
        purchaseOrders.warehouseId,
      ],
    }).onDelete('restrict'),
    index('purchase_receipts_org_order_received_idx').on(
      table.organizationId,
      table.purchaseOrderId,
      table.receivedAt.desc(),
    ),
  ],
);

export const purchaseReceiptItems = pgTable(
  'purchase_receipt_items',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id').notNull(),
    receiptId: uuid('receipt_id').notNull(),
    purchaseOrderId: uuid('purchase_order_id').notNull(),
    purchaseOrderItemId: uuid('purchase_order_item_id').notNull(),
    quantity: integer('quantity').notNull(),
    /** The ledger row this receipt line produced. */
    inventoryMovementId: uuid('inventory_movement_id').notNull(),
  },
  (table) => [
    unique('purchase_receipt_items_org_id_key').on(table.organizationId, table.id),
    unique('purchase_receipt_items_receipt_line_key').on(
      table.organizationId,
      table.receiptId,
      table.purchaseOrderItemId,
    ),
    unique('purchase_receipt_items_movement_key').on(table.inventoryMovementId),
    // The receipt and the order line must belong to the same order (and organization).
    foreignKey({
      name: 'purchase_receipt_items_receipt_fk',
      columns: [table.organizationId, table.receiptId, table.purchaseOrderId],
      foreignColumns: [
        purchaseReceipts.organizationId,
        purchaseReceipts.id,
        purchaseReceipts.purchaseOrderId,
      ],
    }).onDelete('restrict'),
    foreignKey({
      name: 'purchase_receipt_items_line_fk',
      columns: [table.organizationId, table.purchaseOrderId, table.purchaseOrderItemId],
      foreignColumns: [
        purchaseOrderItems.organizationId,
        purchaseOrderItems.purchaseOrderId,
        purchaseOrderItems.id,
      ],
    }).onDelete('restrict'),
    foreignKey({
      name: 'purchase_receipt_items_movement_fk',
      columns: [table.organizationId, table.inventoryMovementId],
      foreignColumns: [inventoryMovements.organizationId, inventoryMovements.id],
    }).onDelete('restrict'),
    index('purchase_receipt_items_org_line_idx').on(
      table.organizationId,
      table.purchaseOrderItemId,
    ),
    check('purchase_receipt_items_quantity_check', sql`${table.quantity} > 0`),
  ],
);

// ---- integration --------------------------------------------------------------------------------

export const outboxEvents = pgTable(
  'outbox_events',
  {
    id: uuid('id').primaryKey(),
    type: text('type').notNull(),
    version: integer('version').notNull(),
    occurredAt: timestamptz('occurred_at').notNull(),
    organizationId: uuid('organization_id'),
    actorId: uuid('actor_id'),
    correlationId: text('correlation_id').notNull(),
    causationId: uuid('causation_id'),
    payload: jsonb('payload').notNull(),
    publishedAt: timestamptz('published_at'),
  },
  (table) => [
    index('outbox_events_unpublished_idx')
      .on(table.occurredAt)
      .where(sql`${table.publishedAt} is null`),
  ],
);

export const schema = {
  memberDirectory,
  categories,
  suppliers,
  warehouses,
  products,
  productVariants,
  productImages,
  inventoryLevels,
  inventoryMovements,
  inventoryReservations,
  purchaseOrderCounters,
  purchaseOrders,
  purchaseOrderItems,
  purchaseReceipts,
  purchaseReceiptItems,
  outboxEvents,
};
export type OperationsSchema = typeof schema;
